def validate_l1_output(llm_output: str, previous_l1: dict) -> dict:
    # Parse JSON
    try:
        new_l1 = json.loads(llm_output)
    except json.JSONDecodeError:
        raise ValidationError("Invalid JSON output")

    # Schema validation
    required_fields = ["occupation", "expertise_domains", "communication_style"]
    for field in required_fields:
        if field not in new_l1["data"]:
            raise ValidationError(f"Missing required field: {field}")

    # Confidence bounds
    for domain in new_l1["data"]["expertise_domains"]:
        if not 0 <= domain["confidence"] <= 1:
            raise ValidationError("Confidence out of bounds")

    # Major change detection
    if previous_l1:
        if new_l1["data"]["occupation"]["primary"] != previous_l1["data"]["occupation"]["primary"]:
            if new_l1["data"]["occupation"]["confidence"] < 0.85:
                # Require high confidence for occupation change
                new_l1["data"]["occupation"] = previous_l1["data"]["occupation"]
                new_l1["metadata"]["change_rejected"] = "insufficient_confidence"

    return new_l1
